const std = @import("std"); const builtin = @import("builtin"); const winz = std.os.windows;
pub const PausCode = enum { okzz, none, done, same, fail };
pub fn codeResp(code: PausCode, onzz: bool) struct { stat: u16, text: []const u8, body: []const u8 } { return switch (code) { .okzz => if (onzz) .{ .stat = 200, .text = "OK", .body = "{\"ok\":true,\"paused\":true}" } else .{ .stat = 200, .text = "OK", .body = "{\"ok\":true,\"paused\":false}" }, .none, .done => .{ .stat = 409, .text = "Conflict", .body = "{\"error\":\"not_running\"}" }, .same => if (onzz) .{ .stat = 409, .text = "Conflict", .body = "{\"error\":\"already_paused\"}" } else .{ .stat = 409, .text = "Conflict", .body = "{\"error\":\"not_paused\"}" }, .fail => .{ .stat = 500, .text = "Internal Server Error", .body = "{\"error\":\"freeze_failed\"}" } }; }
pub const CF = .{ .clas = 18, .oper = 1, .snap = 4096, .rond = 8, .pbuf = 40, .sbuf = 1024 };
extern "kernel32" fn SetInformationJobObject(hJob: winz.HANDLE, class: c_int, info: *anyopaque, len: u32) callconv(.winapi) c_int;
const FrezInfo = extern struct { flag: u32 = CF.oper, frez: u8 = 0, swap: u8 = 0, rese: [2]u8 = .{ 0, 0 }, wake_high: u32 = 0, wake_low: u32 = 0 };
pub const Proc = struct { pidz: i32, ppid: i32, pgrp: i32 };
pub fn statPars(strz: []const u8) ?Proc { const lpar = std.mem.indexOfScalar(u8, strz, '(') orelse return null; const rpar = std.mem.lastIndexOfScalar(u8, strz, ')') orelse return null; if (rpar < lpar) return null; const pidz = std.fmt.parseInt(i32, std.mem.trim(u8, strz[0..lpar], " "), 10) catch return null; var iter = std.mem.tokenizeScalar(u8, strz[rpar + 1 ..], ' '); _ = iter.next() orelse return null; const ppid = std.fmt.parseInt(i32, iter.next() orelse return null, 10) catch return null; const pgrp = std.fmt.parseInt(i32, iter.next() orelse return null, 10) catch return null; return .{ .pidz = pidz, .ppid = ppid, .pgrp = pgrp }; }
pub fn treeColl(list: []const Proc, root: i32, mark: []bool) usize { var coun: usize = 0; for (list, 0..) |item, indx| { mark[indx] = item.pidz == root or item.pgrp == root; if (mark[indx]) coun += 1; } var chan = true; while (chan) { chan = false; for (list, 0..) |item, indx| { if (mark[indx]) continue; for (list, 0..) |pare, pind| { if (!mark[pind] or pare.pidz != item.ppid) continue; mark[indx] = true; coun += 1; chan = true; break; } } } return coun; }
fn procSnap(iozz: std.Io, list: []Proc) usize { if (builtin.os.tag != .linux) return 0; var dirz = std.Io.Dir.cwd().openDir(iozz, "/proc", .{ .iterate = true }) catch return 0; defer dirz.close(iozz); var iter = dirz.iterate(); var coun: usize = 0; while (iter.next(iozz) catch null) |entr| { if (coun >= list.len) break; const pidz = std.fmt.parseInt(i32, entr.name, 10) catch continue; var pbuf: [CF.pbuf]u8 = undefined; const path = std.fmt.bufPrint(&pbuf, "/proc/{d}/stat", .{pidz}) catch continue; var file = std.Io.Dir.cwd().openFile(iozz, path, .{}) catch continue; defer file.close(iozz); var buff: [CF.sbuf]u8 = undefined; const size = file.readPositionalAll(iozz, &buff, 0) catch continue; if (statPars(buff[0..size])) |item| { list[coun] = item; coun += 1; } } return coun; }
fn posiSend(iozz: std.Io, root: i32, sigz: std.posix.SIG) void { std.posix.kill(-root, sigz) catch {}; var snap: [CF.snap]Proc = undefined; var mark: [CF.snap]bool = undefined; var last: usize = 0; var rond: usize = 0; while (rond < CF.rond) : (rond += 1) { const coun = procSnap(iozz, &snap); if (coun == 0) return; const memb = treeColl(snap[0..coun], root, mark[0..coun]); for (snap[0..coun], 0..) |item, indx| { if (mark[indx] and item.pidz != root) std.posix.kill(item.pidz, sigz) catch {}; } if (memb == last) return; last = memb; } }
pub fn treeFrez(iozz: std.Io, jobz: ?winz.HANDLE, lead: ?std.process.Child.Id, onzz: bool) bool { if (builtin.os.tag == .windows) { const hand = jobz orelse return false; var info: FrezInfo = .{ .frez = if (onzz) 1 else 0 }; return SetInformationJobObject(hand, CF.clas, &info, @sizeOf(FrezInfo)) != 0; } else { const pidz: i32 = @intCast(lead orelse return false); if (pidz <= 1) return false; posiSend(iozz, pidz, if (onzz) std.posix.SIG.STOP else std.posix.SIG.CONT); return true; } }
